#!/usr/bin/env python3
"""Safely apply the consolidated qmjyOS Phase 3 runtime patch.

- Verifies the repository and every original file hash before changing anything.
- Creates timestamped backups under build/repairs.
- Stages and verifies all new files before atomic replacement.
- Rolls back replaced files on an application error.
- Never git-adds, commits, pushes, or contacts a remote.
"""
from __future__ import annotations
import argparse, base64, hashlib, json, os, shutil, stat, subprocess, sys
from datetime import datetime
from pathlib import Path

